<body>
    <h1>♔ Mate in 1 Practice</h1>

    <div class="scenario-info" id="scenarioInfo">Select a scenario to begin</div>

    <div class="controls">
        <button id="scenario1">Scenario 1</button>
        <button id="scenario2">Scenario 2</button>
        <button id="scenario3">Scenario 3</button>
        <button id="reset">♻ Reset</button>
    </div>

    <div class="board-container">
        <div class="file-labels">
            <span>a</span><span>b</span><span>c</span><span>d</span>
            <span>e</span><span>f</span><span>g</span><span>h</span>
        </div>
        <div class="board-wrapper">
            <div class="rank-labels">
                <span>8</span><span>7</span><span>6</span><span>5</span>
                <span>4</span><span>3</span><span>2</span><span>1</span>
            </div>
            <div class="board" id="board"></div>
        </div>
    </div>

    <div class="move-indicator">White to move - <span>Find the checkmate!</span></div>

    <div class="feedback" id="feedback"></div>

    <p class="hint">💡 Click a piece then click destination, or drag and drop</p>

    <script>
        // Chess pieces Unicode
        const PIECES = {
            'K': '♔', 'Q': '♕', 'R': '♖', 'B': '♗', 'N': '♘', 'P': '♙',
            'k': '♚', 'q': '♛', 'r': '♜', 'b': '♝', 'n': '♞', 'p': '♟'
        };

        // Scenarios - mate in 1 for white
        const scenarios = {
            1: {
                name: "Back Rank Mate",
                description: "The enemy king is trapped behind his own pawns. Deliver the fatal blow!",
                position: {
                    'g1': 'K',  // White King
                    'd1': 'Q',  // White Queen
                    'g8': 'k',  // Black King
                    'f7': 'p',  // Black pawns creating back rank weakness
                    'g7': 'p',
                    'h7': 'p'
                },
                solution: { from: 'd1', to: 'd8', piece: 'Q' },
                hint: "The 8th rank is deadly for the black king..."
            },
            2: {
                name: "King & Queen Coordination",
                description: "Your King and Queen work together to trap the enemy monarch!",
                position: {
                    'h6': 'K',  // White King controls escape squares
                    'f5': 'Q',  // White Queen ready to strike
                    'h8': 'k'   // Black King in the corner
                },
                solution: { from: 'f5', to: 'f8', piece: 'Q' },
                hint: "The King cuts off escape routes g7 and h7..."
            },
            3: {
                name: "Queen Cage",
                description: "Use your pieces to create an inescapable cage around the black king!",
                position: {
                    'g6': 'K',  // White King
                    'e5': 'Q',  // White Queen
                    'g8': 'k',  // Black King
                    'h7': 'p'   // Black pawn blocks its own king
                },
                solution: { from: 'e5', to: 'e8', piece: 'Q' },
                hint: "The black pawn on h7 is actually helping you..."
            }
        };

        let currentScenario = null;
        let currentScenarioNum = null;
        let currentPosition = {};
        let selectedSquare = null;
        let gameOver = false;
        let moveCount = 0;

        // Initialize board
        function createBoard() {
            const board = document.getElementById('board');
            board.innerHTML = '';

            for (let row = 0; row < 8; row++) {
                for (let col = 0; col < 8; col++) {
                    const square = document.createElement('div');
                    const squareId = String.fromCharCode(97 + col) + (8 - row);
                    square.id = squareId;
                    square.className = 'square ' + ((row + col) % 2 === 0 ? 'light' : 'dark');
                    square.dataset.square = squareId;

                    // Click handler
                    square.addEventListener('click', () => handleSquareClick(squareId));

                    // Drag and drop handlers
                    square.addEventListener('dragover', handleDragOver);
                    square.addEventListener('dragleave', handleDragLeave);
                    square.addEventListener('drop', (e) => handleDrop(e, squareId));

                    board.appendChild(square);
                }
            }
        }

        // Render position on board
        function renderPosition() {
            // Clear all pieces
            document.querySelectorAll('.square').forEach(sq => {
                sq.innerHTML = '';
                sq.classList.remove('highlight', 'selected', 'wrong', 'valid-move', 'drag-over');
            });

            // Place pieces
            for (const [square, piece] of Object.entries(currentPosition)) {
                const squareEl = document.getElementById(square);
                if (squareEl) {
                    const pieceEl = document.createElement('span');
                    const isWhite = piece === piece.toUpperCase();
                    pieceEl.className = 'piece ' + (isWhite ? 'white-piece' : 'black-piece');
                    pieceEl.textContent = PIECES[piece];
                    pieceEl.draggable = isWhite && !gameOver;
                    pieceEl.dataset.piece = piece;
                    pieceEl.dataset.square = square;

                    if (isWhite && !gameOver) {
                        pieceEl.addEventListener('dragstart', (e) => handleDragStart(e, square, piece));
                        pieceEl.addEventListener('dragend', handleDragEnd);
                    }

                    squareEl.appendChild(pieceEl);
                }
            }
        }

        // Load scenario
        function loadScenario(num) {
            currentScenarioNum = num;
            currentScenario = scenarios[num];
            currentPosition = { ...currentScenario.position };
            selectedSquare = null;
            gameOver = false;
            moveCount = 0;

            // Update UI
            document.querySelectorAll('.controls button').forEach(btn => {
                if (btn.id !== 'reset') {
                    btn.classList.remove('active');
                }
            });
            document.getElementById('scenario' + num).classList.add('active');
            document.getElementById('scenarioInfo').innerHTML = 
                `<strong>${currentScenario.name}</strong>: ${currentScenario.description}`;

            hideFeedback();
            renderPosition();
        }

        // Handle square click (for point-and-click movement)
        function handleSquareClick(squareId) {
            if (gameOver || !currentScenario) return;

            const piece = currentPosition[squareId];
            const squareEl = document.getElementById(squareId);

            if (selectedSquare) {
                // Try to move
                if (squareId !== selectedSquare) {
                    const movingPiece = currentPosition[selectedSquare];
                    if (movingPiece && movingPiece === movingPiece.toUpperCase()) {
                        tryMove(selectedSquare, squareId);
                    }
                }
                clearSelection();
            } else if (piece && piece === piece.toUpperCase()) {
                // Select white piece
                clearSelection();
                selectedSquare = squareId;
                squareEl.classList.add('selected');
                showValidMoves(squareId, piece);
            }
        }

        // Show valid moves (simplified - just visual hints)
        function showValidMoves(from, piece) {
            // For this puzzle, we just highlight the solution square subtly
            // In a full implementation, you'd calculate all legal moves
        }

        // Clear selection
        function clearSelection() {
            selectedSquare = null;
            document.querySelectorAll('.square').forEach(sq => {
                sq.classList.remove('selected', 'valid-move');
            });
        }

        // Drag and drop handlers
        function handleDragStart(e, square, piece) {
            if (gameOver) {
                e.preventDefault();
                return;
            }

            e.dataTransfer.setData('text/plain', JSON.stringify({ square, piece }));
            e.dataTransfer.effectAllowed = 'move';

            // Add dragging class
            setTimeout(() => {
                e.target.classList.add('dragging');
            }, 0);

            clearSelection();
            selectedSquare = square;
            document.getElementById(square).classList.add('selected');
        }

        function handleDragEnd(e) {
            e.target.classList.remove('dragging');
            clearSelection();
        }

        function handleDragOver(e) {
            e.preventDefault();
            e.dataTransfer.dropEffect = 'move';
            e.currentTarget.classList.add('drag-over');
        }

        function handleDragLeave(e) {
            e.currentTarget.classList.remove('drag-over');
        }

        function handleDrop(e, targetSquare) {
            e.preventDefault();
            e.currentTarget.classList.remove('drag-over');

            if (gameOver) return;

            try {
                const data = JSON.parse(e.dataTransfer.getData('text/plain'));
                const fromSquare = data.square;
                const piece = data.piece;

                if (fromSquare && piece === piece.toUpperCase()) {
                    tryMove(fromSquare, targetSquare);
                }
            } catch (err) {
                console.error('Drop error:', err);
            }

            clearSelection();
        }

        // Try to make a move
        function tryMove(from, to) {
            if (!currentScenario || from === to) return;

            const piece = currentPosition[from];
            if (!piece || piece !== piece.toUpperCase()) return;

            const solution = currentScenario.solution;
            const targetSquareEl = document.getElementById(to);

            moveCount++;

            // Check if this is the correct solution
            if (from === solution.from && to === solution.to) {
                // Correct move - make the move
                delete currentPosition[from];
                currentPosition[to] = piece;
                gameOver = true;

                renderPosition();

                // Highlight the mating square with animation
                targetSquareEl.classList.add('highlight');

                // Show success feedback
                const messages = [
                    'Checkmate! Brilliant! ♔',
                    'Checkmate! Perfect! ✨',
                    'Checkmate! Well done! 🎉'
                ];
                showFeedback(true, messages[currentScenarioNum - 1]);

            } else {
                // Wrong move - show the wrong move temporarily
                const originalPosition = { ...currentPosition };
                delete currentPosition[from];
                currentPosition[to] = piece;

                renderPosition();
                targetSquareEl.classList.add('wrong');

                // Show error feedback
                const errorMessages = [
                    'Not quite right. Try again!',
                    'That\'s not checkmate. Think again!',
                    'The king can escape! Try another move.'
                ];
                showFeedback(false, errorMessages[Math.floor(Math.random() * errorMessages.length)]);

                // Reset after a delay
                setTimeout(() => {
                    currentPosition = originalPosition;
                    renderPosition();
                    hideFeedback();
                }, 1500);
            }
        }

        // Show feedback
        function showFeedback(success, message) {
            const feedback = document.getElementById('feedback');
            feedback.textContent = message;
            feedback.className = 'feedback show ' + (success ? 'success' : 'error');
        }

        // Hide feedback
        function hideFeedback() {
            const feedback = document.getElementById('feedback');
            feedback.classList.remove('show');
        }

        // Reset current scenario
        function resetScenario() {
            if (currentScenarioNum) {
                loadScenario(currentScenarioNum);
            } else {
                loadScenario(1);
            }
        }

        // Event listeners
        document.getElementById('scenario1').addEventListener('click', () => loadScenario(1));
        document.getElementById('scenario2').addEventListener('click', () => loadScenario(2));
        document.getElementById('scenario3').addEventListener('click', () => loadScenario(3));
        document.getElementById('reset').addEventListener('click', resetScenario);

        // Keyboard shortcuts
        document.addEventListener('keydown', (e) => {
            if (e.key === '1') loadScenario(1);
            if (e.key === '2') loadScenario(2);
            if (e.key === '3') loadScenario(3);
            if (e.key === 'r' || e.key === 'R') resetScenario();
            if (e.key === 'Escape') clearSelection();
        });

        // Initialize
        createBoard();
        loadScenario(1);
    </script>
</body>
</html>
```

## Features:

### 3 Mate-in-1 Scenarios:
1. **Back Rank Mate** - Queen delivers checkmate on 8th rank while black pawns trap their own king
2. **King & Queen Coordination** - White King cuts off escape while Queen delivers mate
3. **Queen Cage** - The black pawn blocks its own king's escape

### Interactivity:
- **Drag and Drop** - Grab white pieces and drop them on target squares
- **Click to Move** - Click a piece to select, click destination to move
- **Keyboard Shortcuts** - Press 1/2/3 for scenarios, R to reset

### Visual Feedback:
- **Green pulsing highlight** on successful checkmate
- **Red shake animation** on wrong moves
- **Blue highlight** showing selected pieces
- **Drag-over indicator** when hovering drop targets
- **Success/Error message banners**

### UI Elements:
- Board coordinates (a-h, 1-8)
- Scenario selection buttons
- Reset button
- Scenario descriptions
- Helpful hints

Just open this HTML file in a browser and start practicing your checkmate patterns!
